/* generated by build.py from js/site.js */
/* Faz Power Washing - one file for every page. Every block null-guards. Patterns from the demo + Nueces build. */
(function(){
  'use strict';
  var reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  function esc(s){ return String(s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }

  /* ---- mobile menu ---- */
  var b = document.body, mnav = document.getElementById('mnav'), burger = document.getElementById('burger');
  if (mnav && burger){
    var setMenu = function(open){ b.classList.toggle('menu-open', open); mnav.setAttribute('aria-hidden', open ? 'false' : 'true');
      burger.setAttribute('aria-expanded', open ? 'true' : 'false'); burger.setAttribute('aria-label', open ? 'Close menu' : 'Open menu'); };
    burger.addEventListener('click', function(){ setMenu(!b.classList.contains('menu-open')); });
    mnav.querySelectorAll('a').forEach(function(a){ a.addEventListener('click', function(){ setMenu(false); }); });
    addEventListener('keydown', function(e){ if (e.key === 'Escape' && b.classList.contains('menu-open')){ setMenu(false); burger.focus(); } });
    addEventListener('resize', function(){ if (innerWidth > 1080 && b.classList.contains('menu-open')) setMenu(false); });
  }

  /* ---- desktop dropdowns: click (touch laptops) + hover; outside click / Escape closes ---- */
  var dds = document.querySelectorAll('.dd');
  var closeAll = function(except){ dds.forEach(function(x){ if (x !== except){ x.classList.remove('open'); x.querySelector('button').setAttribute('aria-expanded', 'false'); } }); };
  dds.forEach(function(d){
    var btn = d.querySelector('button'), t = null;
    btn.addEventListener('click', function(e){ e.stopPropagation(); var o = !d.classList.contains('open'); closeAll(d); d.classList.toggle('open', o); btn.setAttribute('aria-expanded', o ? 'true' : 'false'); });
    if (matchMedia('(hover:hover)').matches){
      d.addEventListener('mouseenter', function(){ clearTimeout(t); closeAll(d); d.classList.add('open'); btn.setAttribute('aria-expanded', 'true'); });
      d.addEventListener('mouseleave', function(){ t = setTimeout(function(){ d.classList.remove('open'); btn.setAttribute('aria-expanded', 'false'); }, 180); });
    }
    d.querySelector('.dd-panel').addEventListener('click', function(e){ e.stopPropagation(); });
  });
  document.addEventListener('click', function(){ closeAll(null); });
  addEventListener('keydown', function(e){ if (e.key === 'Escape') closeAll(null); });

  /* ---- home hero video: phones only, skipped for reduced motion / data saver; fades in once it is actually playing ---- */
  var hv = document.querySelector('.hero-vid');
  if (hv && matchMedia('(max-width:760px)').matches && !matchMedia('(prefers-reduced-motion: reduce)').matches
      && !(navigator.connection && navigator.connection.saveData)){
    hv.addEventListener('playing', function(){ hv.classList.add('on'); hv.parentNode.classList.add('vid-on'); }, {once: true});
    hv.src = hv.getAttribute('data-src');
    var pr = hv.play(); if (pr && pr.catch) pr.catch(function(){});
  }

  /* ---- mobile call bar: only after the hero has scrolled away ---- */
  var bar = document.getElementById('mbar'), hero = document.querySelector('.hero, .simple-hero');
  if (bar && hero && 'IntersectionObserver' in window){
    new IntersectionObserver(function(es){
      es.forEach(function(e){ bar.classList.toggle('on', !e.isIntersecting && e.boundingClientRect.top < 0); });
    }, {threshold: 0}).observe(hero);
  } else if (bar) { bar.classList.add('on'); }

  /* ---- maps: the Google embed is heavy, so it loads only when scrolled near ---- */
  var maps = document.querySelectorAll('iframe[data-src]');
  if (maps.length){
    var go = function(i){ if (!i.getAttribute('src')) i.src = i.getAttribute('data-src'); };
    if (!('IntersectionObserver' in window)) maps.forEach(go);
    else { var mio = new IntersectionObserver(function(es){ es.forEach(function(e){ if (e.isIntersecting){ go(e.target); mio.unobserve(e.target); } }); }, {rootMargin: '400px 0px'}); maps.forEach(function(i){ mio.observe(i); }); }
  }

  /* ---- before / after: starts at 80% before; drag the knob to reveal the after ---- */
  document.querySelectorAll('.ba').forEach(function(ba){
    var handle = ba.querySelector('.ba-handle'), pos = 80, dragging = false;
    var set = function(p){ pos = Math.max(0, Math.min(100, p)); ba.style.setProperty('--pos', pos + '%'); handle.setAttribute('aria-valuenow', Math.round(pos)); };
    var fromX = function(x){ var r = ba.getBoundingClientRect(); set((x - r.left) / r.width * 100); };
    /* 11/16 (Jeffrey): only the round arrow knob starts a drag (plus a 14px forgiving ring); tapping the photo does nothing */
    var knob = handle.querySelector('span');
    var onKnob = function(e){ var r = knob.getBoundingClientRect(), m = 14;
      return e.clientX >= r.left - m && e.clientX <= r.right + m && e.clientY >= r.top - m && e.clientY <= r.bottom + m; };
    ba.addEventListener('pointerdown', function(e){
      if (!onKnob(e)) return;
      dragging = true; e.preventDefault();
      try { ba.setPointerCapture(e.pointerId); } catch (_) {}
    });
    ba.addEventListener('pointermove', function(e){ if (dragging) fromX(e.clientX); });
    ['pointerup', 'pointercancel', 'lostpointercapture'].forEach(function(t){ ba.addEventListener(t, function(){ dragging = false; }); });
    handle.addEventListener('keydown', function(e){
      if (e.key === 'ArrowLeft'){ set(pos - 5); e.preventDefault(); }
      if (e.key === 'ArrowRight'){ set(pos + 5); e.preventDefault(); }
    });
    var wrap = ba.closest('.ba-wrap');
    if (!wrap) return;
    var tabs = wrap.querySelectorAll('.tab[data-b]');
    tabs.forEach(function(t){
      t.addEventListener('click', function(){
        tabs.forEach(function(o){ o.classList.toggle('on', o === t); o.setAttribute('aria-pressed', o === t ? 'true' : 'false'); });
        var pics = ba.querySelectorAll('picture');
        var swap = function(pic, key, alt){
          var s = pic.querySelector('source'); s.srcset = '/faz-preview/assets/img/' + key + '-s.webp 400w, /faz-preview/assets/img/' + key + '.webp 800w';
          var im = pic.querySelector('img'); im.src = '/faz-preview/assets/img/' + key + '.jpg'; im.alt = alt;
        };
        swap(pics[0], t.getAttribute('data-a'), t.getAttribute('data-aalt'));
        swap(pics[1], t.getAttribute('data-b'), t.getAttribute('data-balt'));
        ba.style.aspectRatio = t.getAttribute('data-ar');
        set(80);
      });
    });
  });

  /* ---- drifting swipe rows (reviews: every width; service cards: phones only) ----
     --dx transform drift (no scrollLeft rounding jitter); touch/drag hands the offset to scrollLeft so native
     swiping takes over; 3.5s after letting go it folds back into --dx. */
  function drift(row, track, items, speed, mq){
    if (reduce || !items.length) return;
    var originals = Array.prototype.slice.call(items), clones = [];
    originals.forEach(function(n){ var c = n.cloneNode(true); c.classList.add('is-clone'); c.setAttribute('aria-hidden', 'true');
      c.querySelectorAll('a,button').forEach(function(a){ a.setAttribute('tabindex', '-1'); });
      if (c.tagName === 'A') c.setAttribute('tabindex', '-1');
      track.appendChild(c); clones.push(c); });
    var dx = 0, last = 0, held = false, idle = null, visible = false, P = 0;
    var active = function(){ return !mq || matchMedia(mq).matches; };
    /* exact (fractional) loop length: offsetLeft rounds to whole px, which made a faint jump at each wrap / hand-back */
    var period = function(){ return clones[0].getBoundingClientRect().left - originals[0].getBoundingClientRect().left; };
    var paint = function(){ track.style.setProperty('--dx', dx.toFixed(2)); };
    function tick(t){
      requestAnimationFrame(tick);
      if (!last) last = t;
      var dt = Math.min(64, t - last); last = t;
      if (held || !visible || !active()) return;
      P = P || period();
      dx += speed * dt / 1000;
      if (P > 0 && dx >= P) dx -= P;
      paint();
    }
    function grab(){
      if (!active()) return;
      clearTimeout(idle);
      if (!held){ P = period(); held = true; var s = dx < P / 2 ? dx + P : dx; dx = 0; paint(); row.scrollLeft = s; }
    }
    function release(){
      clearTimeout(idle);
      idle = setTimeout(function(){
        if (!active()) return;
        P = period(); var s = row.scrollLeft; dx = P > 0 ? s % P : 0; row.scrollLeft = 0; paint(); held = false; last = 0;
      }, 3500);
    }
    row.addEventListener('touchstart', grab, {passive: true});
    row.addEventListener('touchend', release);
    row.addEventListener('wheel', function(){ grab(); release(); }, {passive: true});
    if (!mq){
      row.addEventListener('mouseenter', grab);
      row.addEventListener('mouseleave', release);
      var down = false, sx = 0, sl = 0;
      row.addEventListener('pointerdown', function(e){ if (e.pointerType !== 'mouse') return; down = true; sx = e.clientX; sl = row.scrollLeft; row.classList.add('drag'); e.preventDefault(); });
      window.addEventListener('pointermove', function(e){ if (down) row.scrollLeft = sl - (e.clientX - sx); });
      window.addEventListener('pointerup', function(){ if (down){ down = false; row.classList.remove('drag'); } });
    }
    if (mq){ var m = matchMedia(mq), onm = function(){ row.classList.toggle('drift', m.matches); dx = 0; paint(); P = 0; }; onm(); m.addEventListener ? m.addEventListener('change', onm) : m.addListener(onm); }
    if ('IntersectionObserver' in window){
      new IntersectionObserver(function(es){ visible = es[0].isIntersecting; last = 0; }, {threshold: .2}).observe(row);
    } else visible = true;
    requestAnimationFrame(tick);
  }
  var rv = document.getElementById('rvRow');
  if (rv) drift(rv, rv.querySelector('.rv-track'), rv.querySelectorAll('.rv'), 32, null);
  document.querySelectorAll('.svc-grid[data-drift]').forEach(function(sg){
    if (sg.querySelectorAll('.svc').length >= 3) drift(sg, sg, sg.querySelectorAll('.svc'), 18, '(max-width: 760px)');
  });

  /* ---- steps: light the circles as they pass (phones get the rail from css) ---- */
  var steps = document.querySelectorAll('.step');
  if (steps.length && 'IntersectionObserver' in window){
    var sio = new IntersectionObserver(function(es){ es.forEach(function(e){ if (e.isIntersecting){ e.target.classList.add('lit'); sio.unobserve(e.target); } }); }, {rootMargin: '0px 0px -38% 0px'});
    steps.forEach(function(s){ sio.observe(s); });
  }

  /* ---- lightbox: any [data-lb] opens window.PHOTOS at that photo ---- */
  var lb = document.getElementById('lb'), P = window.PHOTOS || [];
  if (lb && P.length){
    var strip = document.getElementById('lbStrip'), cnt = document.getElementById('lbC'), i = 0, built = false;
    var build = function(){ strip.innerHTML = P.map(function(p){ return '<figure><img data-src="/faz-preview/assets/img/' + p[0] + '.webp" alt="' + esc(p[1]) + '"></figure>'; }).join(''); built = true; };
    var load = function(k){ [k - 1, k, k + 1].forEach(function(j){ var f = strip.children[j]; if (f){ var im = f.firstChild; if (!im.getAttribute('src')) im.src = im.getAttribute('data-src'); } }); };
    var goTo = function(k, anim){ i = (k + P.length) % P.length; strip.style.transition = anim === false ? 'none' : 'transform .35s cubic-bezier(.2,.7,.2,1)'; strip.style.transform = 'translateX(' + (-i * 100) + '%)'; cnt.textContent = (i + 1) + ' / ' + P.length; load(i); };
    var open = function(id){ if (!built) build(); lb.classList.add('open'); document.body.style.overflow = 'hidden'; var k = 0; P.forEach(function(p, j){ if (p[0] === id) k = j; }); goTo(k, false); document.getElementById('lbX').focus(); };
    var close = function(){ lb.classList.remove('open'); document.body.style.overflow = ''; };
    document.addEventListener('click', function(e){ var t = e.target.closest && e.target.closest('[data-lb]'); if (t){ e.preventDefault(); open(t.getAttribute('data-lb')); } });
    document.getElementById('lbX').onclick = close;
    document.getElementById('lbP').onclick = function(){ goTo(i - 1); };
    document.getElementById('lbN').onclick = function(){ goTo(i + 1); };
    addEventListener('keydown', function(e){ if (!lb.classList.contains('open')) return; if (e.key === 'Escape') close(); if (e.key === 'ArrowLeft') goTo(i - 1); if (e.key === 'ArrowRight') goTo(i + 1); });
    var x0 = null, ddx = 0, w = 1;
    lb.addEventListener('touchstart', function(e){ x0 = e.touches[0].clientX; ddx = 0; w = lb.clientWidth; strip.style.transition = 'none'; }, {passive: true});
    lb.addEventListener('touchmove', function(e){ if (x0 === null) return; ddx = e.touches[0].clientX - x0; strip.style.transform = 'translateX(calc(' + (-i * 100) + '% + ' + ddx + 'px))'; }, {passive: true});
    lb.addEventListener('touchend', function(){ if (x0 === null) return; if (Math.abs(ddx) > w * .18) goTo(i + (ddx < 0 ? 1 : -1)); else goTo(i); x0 = null; });
    lb.addEventListener('click', function(e){ if (e.target === lb || e.target.tagName === 'FIGURE') close(); });
  }

  /* ---- quote form -> Netlify Forms (faz-quote). Step 1 = what, step 2 = who. Confirmation only after a 2xx. ---- */
  function usPhone(raw){
    var s = String(raw).trim(), d = s.replace(/\D/g, '');
    if (s.charAt(0) === '+' && d.charAt(0) !== '1') return null;
    if (d.length === 11 && d.charAt(0) === '1') d = d.slice(1);
    if (d.length !== 10 || /^(\d)\1{9}$/.test(d)) return null;
    var npa = d.slice(0, 3), nxx = d.slice(3, 6);
    if (npa.charAt(0) < '2' || npa.charAt(1) === '9' || (npa.charAt(1) === '1' && npa.charAt(2) === '1')) return null;
    if (nxx.charAt(0) < '2' || (nxx.charAt(1) === '1' && nxx.charAt(2) === '1')) return null;
    if (nxx === '555' && d.slice(6, 8) === '01') return null;
    return '(' + npa + ') ' + nxx + '-' + d.slice(6);
  }
  var f = document.getElementById('qwiz');
  if (f){
    var stepsF = f.querySelectorAll('.qw-s'), cur = 1, N = 2,
        lbl = f.querySelector('.qw-step'), barF = f.querySelector('.qw-bar span'), back = f.querySelector('.qw-back'),
        err = f.querySelector('.form-err'), btn = f.querySelector('.qw-submit'), bl = btn.querySelector('.lbl'), skip = false;
    f.elements.page.value = location.pathname;
    var show = function(n, focus){
      cur = n;
      stepsF.forEach(function(s){ s.classList.toggle('on', +s.getAttribute('data-step') === n); });
      lbl.textContent = 'Step ' + n + ' of ' + N; barF.style.width = (n / N * 100) + '%';
      back.hidden = n === 1 || skip;
      if (n === 2 && focus && innerWidth > 760){ var nm = f.elements.name; setTimeout(function(){ nm.focus({preventScroll: true}); }, 60); }
    };
    var pick = function(v){
      var o = null;
      f.querySelectorAll('.opt').forEach(function(x){ var on = x.getAttribute('data-value') === v; x.classList.toggle('sel', on); x.setAttribute('aria-pressed', on ? 'true' : 'false'); if (on) o = x; });
      if (o) f.elements.service.value = v;
      return o;
    };
    f.querySelectorAll('.opt').forEach(function(o){
      o.addEventListener('click', function(){ pick(o.getAttribute('data-value')); skip = false; setTimeout(function(){ show(2, true); }, 260); });
    });
    back.addEventListener('click', function(){ show(1); });
    var pre = f.getAttribute('data-preset');
    if (pre && pick(pre)){ skip = false; }
    /* "Get a free quote" on a service hero pre-picks that service and opens step 2 */
    document.querySelectorAll('[data-pick]').forEach(function(a){
      a.addEventListener('click', function(){ if (pick(a.getAttribute('data-pick'))){ skip = false; show(2, false); } });
    });
    var ph = f.elements.phone, em = f.elements.email;
    ph.addEventListener('input', function(){
      if (ph.selectionStart !== ph.value.length || ph.value.charAt(0) === '+') return;
      var d = ph.value.replace(/\D/g, ''); if (d.length > 10) return;
      if (d.length > 6) ph.value = '(' + d.slice(0, 3) + ') ' + d.slice(3, 6) + '-' + d.slice(6);
      else if (d.length > 3) ph.value = '(' + d.slice(0, 3) + ') ' + d.slice(3);
    });
    f.addEventListener('keydown', function(e){ if (e.key === 'Enter' && cur < N && e.target.tagName !== 'TEXTAREA') e.preventDefault(); });
    f.addEventListener('submit', function(e){
      e.preventDefault(); if (cur < N) return;
      var ok = true, nm = f.elements.name;
      f.querySelector('.f-name').classList.toggle('bad', !nm.value.trim()); if (!nm.value.trim()) ok = false;
      var good = usPhone(ph.value); f.querySelector('.f-phone').classList.toggle('bad', !good); if (!good) ok = false; else ph.value = good;
      var ev = em.value.trim(), eok = !ev || /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(ev); f.querySelector('.f-email').classList.toggle('bad', !eok); if (!eok) ok = false;
      if (!ok){ var bad = f.querySelector('.field.bad input'); if (bad) bad.focus(); return; }
      /* preview hosts (localhost, zonkelmedia.com) have no Netlify Forms: say so instead of failing */
      if (/zonkelmedia\.com$|github\.io$|^localhost$|^127\.|^$/.test(location.hostname)){
        err.innerHTML = 'Preview only: this form goes live with the real site and sends straight to Moises. For now, call <a href="tel:+13617779140">(361)&nbsp;777-9140</a>.';
        err.hidden = false; return;
      }
      btn.disabled = true; var old = bl.textContent; bl.textContent = 'Sending…'; err.hidden = true;
      fetch('/faz-preview/', {method: 'POST', headers: {'Content-Type': 'application/x-www-form-urlencoded'}, body: new URLSearchParams(new FormData(f)).toString()})
        .then(function(r){ if (!r.ok) throw new Error(r.status); location.href = '/faz-preview/thank-you/'; })
        .catch(function(){ btn.disabled = false; bl.textContent = old; err.innerHTML = 'That didn’t go through. Please call <a href="tel:+13617779140">(361)&nbsp;777-9140</a>.'; err.hidden = false; });
    });
    show(1);
  }
})();
